window.AUTH=window.AUTH||{};window.AUTH["22-846"]={"d":"22-846","id":"2023/22-846","n":"Department of Agriculture Rural Development Rural Housing Service v. Kirtz","briefs":[{"k":"petitioner","label":"Brief of petitioner Department of Agriculture Rural Development Rural Housing Service","date":"2023-08-15","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/275398/20230815163427932_22-846%20USDA%20v.%20Kirtz.pdf","side":"pet","n":120},{"k":"respondent","label":"Brief of respondent Reginald Kirtz","date":"2023-09-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/280393/20230925150024945_Final%20brief.pdf","side":"res","n":164},{"k":"reply","label":"Reply of petitioner Department of Agriculture Rural Development Rural Housing Service","date":"2023-10-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-846/286107/20231025175458840_22-846%20USDA%20Rural%20Development%20Rural%20Housing%20Serv.%20v.%20Kirtz.pdf","side":"pet","n":64}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r03_4gcj.pdf","tr":true,"items":[{"t":"case","label":"Abitron Austria GmbH v. Hetronic Int’l, Inc.","cite":"2023 WL 4239255","y":2023,"court":"June 29","by":{"0":"32, 33"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"op":2,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"13, 16","1":"38"}},{"t":"case","label":"Atascadero State Hospital v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"op":4,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 21, 23","2":"5"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"ar":2,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"32","1":"27, 28","2":"11"}},{"t":"case","label":"City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"sum":"The mere retention of estate property after the filing of a bankruptcy petition does not violate 11 U. S. C. §362(a)(3), which operates as a “stay” of “any act” to “exercise control” over the property of the estate.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"Daniel v. National Park Service","cite":"891 F.3d 762","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/762/","by":{"0":"35"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"op":3,"sum":"Rejecting the use of legislative history when assessing whether Congress abrogated sovereign immunity.","sumSrc":"opinion","by":{"0":"28","1":"35, 39, 46"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"sum":"The Court reasoned that \"a straightforward textual analysis\" of the Privacy Act shows that the statute guarantees the $1000 minimum for victims of willful Privacy Act violations only in relation to \"actual damages sustained.\" Individuals subjected to an adverse effect - like the miners in this case - have \"injury enough to open the courthouse door, but without more\" have \"no cause of action for damages under the Privacy Act.\".","sumSrc":"Oyez","by":{"0":"37, 38"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Employees of the Department of Public Health & Welfare v. Department of Public Health & Welfare","cite":"411 U.S. 279","y":1973,"id":"1972/71-1021","sc":1,"op":10,"ar":40,"sum":"Noting “[p]ortions of the Court's opinion convey th[at] impression”.","sumSrc":"opinion","by":{"0":"10, 25-28","1":"6, 7, 37, 43–47","2":"6"}},{"t":"case","label":"Environmental Defense v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"op":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"0":"29","2":"14"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":2,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"9, 15, 20, 36","1":"12, 13, 39, 41, 42","2":"4, 12"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":2,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 13, 14","1":"37, 38","2":"10, 16"}},{"t":"case","label":"Financial Oversight & Management Board for Puerto Rico v. Centro de Periodismo Investigativo, Inc.","cite":"143 S. Ct. 1176","y":2023,"id":"2022/22-96","sc":1,"op":5,"ar":3,"sum":"Nothing in the Puerto Rico Oversight, Management, and Economic Stability Act—including its jurisdictional provision, 48 U. S. C. §2126(a)—categorically abrogates any sovereign immunity the Financial Oversight and Management Board for Puerto Rico enjoys from legal claims.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9, 14-21","1":"12, 13, 36, 37, 38","2":"1, 3, 4, 8-10"}},{"t":"case","label":"Fitzpatrick v. IRS","cite":"665 F.2d 327","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/665/327/","by":{"0":"38"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"35","1":"31"}},{"t":"case","label":"International Primate Protection League v. Administrators of Tulane Educational Fund","cite":"500 U.S. 72","y":1991,"id":"1990/90-89","sc":1,"sum":"Petitioners, organizations and individuals seeking the humane treatment of animals, filed suit in a Louisiana court to enjoin respondents, the Institutes for Behavior Resources (IBR), the National Institutes of Health (NIH), and the Administrators of the Tulane Educational Fund (Tulane), from using certain monkeys for federally funded medical experiments and to obtain custody over the animals. NIH removed the case …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Kimel v. Florida Board of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"op":9,"ar":5,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"0":"19, 20","1":"26, 39, 40, 47","2":"8, 9"}},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"143 S. Ct. 1689","y":2023,"id":"2022/22-227","sc":1,"op":2,"ar":2,"sum":"The Bankruptcy Code unequivocally abrogates the sovereign immunity of all governments, including federally recognized Indian tribes.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17","1":"12, 13, 14, 27, 30, 41, 42"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"op":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"6, 15, 20","1":"39"}},{"t":"case","label":"Middlesex County Sewerage Authority v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Nevada Department of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"op":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"19","1":"40","2":"8"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Return Mail, Inc. v. United States Postal Service","cite":"139 S. Ct. 1853","y":2019,"id":"2018/17-1594","sc":1,"sum":"The Federal Government is not a “person” capable of petitioning the Patent Trial and Appeal Board to institute patent review proceedings under the Leahy-Smith America Invents Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 29, 30","1":"21"}},{"t":"case","label":"Robinson v. Department of Education","cite":"140 S. Ct. 1440","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/1440/","sc":1,"by":{"0":"38"}},{"t":"case","label":"Robinson v. United States Department of Education","cite":"917 F.3d 799","y":2019,"url":"https://www.courtlistener.com/c/F.3d/917/799/","by":{"0":"34","1":"28","2":"8"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"op":7,"ar":3,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"11, 18, 34","1":"10, 28, 30","2":"8, 18"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"op":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"0":"13, 15, 21, 39","1":"12, 42","2":"5"}},{"t":"case","label":"Spector v. Norwegian Cruise Line Ltd.","cite":"545 U.S. 119","y":2005,"id":"2004/03-1388","sc":1,"sum":"The Court held 6-3 that Title III applied to foreign-flag cruise ships in U.S. waters. Justice Kennedy delivered the Court's controlling opinion, which held that Title III did not apply to foreign ships' internal affairs, because there was no \"clear congressional statement\" showing an intent to do so. A clear statement was necessary before a general law could interfere with a foreign-vessel's internal affairs.","sumSrc":"Oyez","by":{"0":"21","1":"42, 43"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"2, 3, 19"}},{"t":"case","label":"United States v. California","cite":"297 U.S. 175","y":1936,"id":"scdb/1935-140","sc":1,"sum":"Assistant Solicitor General Bell, with whom Solicitor General Reed, Assistant Attorney General Keenan, and. Messrs. David V. Cahill, M. S. Huberman, Charles E. Wysanski, Jr., and Daniel W. Knoiolton were on the brief, for the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32","1":"26"}},{"t":"case","label":"United States v. Cooper Corp.","cite":"312 U.S. 600","y":1941,"id":"scdb/1940-054","sc":1,"sum":"1. While the United States is a juristic person in the sense that it can sue upon its contracts or in vindication of its property rights, the term \"person\" does not include the sovereign, in common usage, nor, ordinarily, when employed in statutes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","2":"15"}},{"t":"case","label":"United States v. Idaho","cite":"508 U.S. 1","y":1993,"id":"1992/92-190","sc":1,"sum":"The McCarran Amendment does not waive the United States' sovereign immunity from fees of the kind sought by Idaho. While \"fees\" and \"costs\" generally mean two different things in the context of lawsuits, the line is blurred, indeed, in the context of this proceeding. UNITED STATES v. IDAHO EX REL. DIRECTOR, IDAHO DEPT. OF WATER RESOURCES Whereas Idaho courts used to proportionately tax the \"costs\" against all …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"op":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7","2":"13"}},{"t":"case","label":"United States v. Public Utilities Commission","cite":"345 U.S. 295","y":1953,"id":"scdb/1952-073","sc":1,"sum":"The rates for such sales of power for resale are subject to regulation by the Federal Power Commission under Part II of the Federal Power Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","1":"20, 21"}},{"t":"case","label":"United States v. Shaw","cite":"309 U.S. 495","y":1940,"id":"scdb/1939-063","sc":1,"sum":"1. A suit against the United States may be brought only with consent given, and in the courts designated, by statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"United States v. Sherwood","cite":"312 U.S. 584","y":1941,"id":"scdb/1940-058","sc":1,"sum":"A New York court, acting under authority of § 795 of the New York Civil Practice Act, made an order authorizing a judgment creditor to sue under the Tucker Act, to recover damages from the United States for breach of its contract with the. judgment debtor, the order directing that out of the recovery the judgment creditor should be entitled to a sum sufficient to satisfy his judgment with interest, costs, etc. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13","1":"11"}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"op":1,"sum":"Respondent Government trial attorneys with civil service grade GS-13 classifications requested their employing agency to reclassify their positions to grade GS-14, contending that their duties and responsibilities met the requirements for the higher grade and were identical to those of other trial attorneys classified as GS-14 in another agency, and that under the principle of \"equal pay for substantially equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 13"}},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"sum":"Section 1346(a)(1) authorizes a refund suit by a party who, though not assessed a tax, paid the tax under protest to remove a federal tax lien from her property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 7, 20","1":"28, 39"}},{"t":"case","label":"United States Department of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","1":"25"}},{"t":"case","label":"Utility Air Regulatory Group v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"ar":12,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"10, 28, 30","1":"20","2":"14"}},{"t":"case","label":"Wyatt v. Cole","cite":"504 U.S. 158","y":1992,"id":"1991/91-126","sc":1,"sum":"With the assistance of respondent Robbins, an attorney, respondent Cole filed a complaint under the Mississippi replevin statute against his partner, petitioner Wyatt. After Cole refused to comply with a state court order to return to Wyatt property seized under the statute, Wyatt brought suit in the Federal District Court under 42 U. S. C. § 1983, challenging the state statute's constitutionality and seeking …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"0":"11, 34"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"17","2":"3"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"17","2":"3"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 1681b","url":"https://www.law.cornell.edu/uscode/text/15/1681b","subs":["(b)(2)","(a)(1)","(a)(3)","(b)(3)(A)","(b)(4)(A)","(f)"],"stext":{"head":"§1681b. Permissible purposes of consumer reports","paras":[[0,"(a) In general"],[0,"Subject to subsection (c), any consumer reporting agency may furnish a consumer report under the following circumstances and no other:"],[1,"(1) In response to the order of a court having jurisdiction to issue such an order, a subpoena issued in connection with proceedings before a Federal grand jury, or a subpoena issued in accordance with section 5318 of title 31 or section 3486 of title 18."],[1,"(2) In accordance with the written instructions of the consumer to whom it relates."],[1,"(3) To a person which it has reason to believe—"],[2,"(A) intends to use the information in connection with a credit transaction involving the consumer on whom the information is to be furnished and involving the extension of credit to, or review or collection of an account of, the consumer; or"],[2,"(B) intends to use the information for employment purposes; or"],[2,"(C) intends to use the information in connection with the underwriting of insurance involving the consumer; or"],[2,"(D) intends to use the information in connection with a determination of the consumer's eligibility for a license or other benefit granted by a governmental instrumentality required by law to consider an applicant's financial responsibility or status; or"],[2,"(E) intends to use the information, as a potential investor or servicer, or current insurer, in connection with a valuation of, or an assessment of the credit or prepayment risks associated with, an existing credit obligation; or"],[2,"(F) otherwise has a legitimate business need for the information—"],[3,"(i) in connection with a business transaction that is initiated by the consumer; or"],[3,"(ii) to review an account to determine whether the consumer continues to meet the terms of the account."],[2,"(G) executive departments and agencies in connection with the issuance of government-sponsored individually-billed travel charge cards."],[1,"(4) In response to a request by the head of a State or local child support enforcement agency (or a State or local government official authorized by the head of such an agency), if the person making the request certifies to the consumer reporting agency that—"],[2,"(A) the consumer report is needed for the purpose of establishing an individual's capacity to make child support payments, determining the appropriate level of such payments, or enforcing a child support order, award, agreement, or judgment;"],[2,"(B) the parentage of the consumer for the child to which the obligation relates has been established or acknowledged by the consumer in accordance with State laws under which the obligation arises (if required by those laws); and"],[2,"(C) the consumer report will be kept confidential, will be used solely for a purpose described in subparagraph (A), and will not be used in connection with any other civil, administrative, or criminal proceeding, or for any other purpose."],[1,"(5) To an agency administering a State plan under section 654 of title 42 for use to set an initial or modified child support award."],[1,"(6) To the Federal Deposit Insurance Corporation or the National Credit Union Administration as part of its preparation for its appointment or as part of its exercise of powers, as conservator, receiver, or liquidating agent for an insured depository institution or insured credit union under the Federal Deposit Insurance Act [12 U.S.C. 1811 et seq.] or the Federal Credit Union Act [12 U.S.C. 1751 et seq.], or other applicable Federal or State law, or in connection with the resolution or liquidation of a failed or failing insured depository institution or insured credit union, as applicable."],[0,"(b) Conditions for furnishing and using consumer reports for employment purposes"],[0,"(1) Certification from user"],[1,"A consumer reporting agency may furnish a consumer report for employment purposes only if—"],[2,"(A) the person who obtains such report from the agency certifies to the agency that—"],[3,"(i) the person has complied with paragraph (2) with respect to the consumer report, and the person will comply with paragraph (3) with respect to the consumer report if paragraph (3) becomes applicable; and"],[3,"(ii) information from the consumer report will not be used in violation of any applicable Federal or State equal employment opportunity law or regulation; and"],[2,"(B) the consumer reporting agency provides with the report, or has previously provided, a summary of the consumer's rights under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(2) Disclosure to consumer"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), a person may not procure a consumer report, or cause a consumer report to be procured, for employment purposes with respect to any consumer, unless—"],[3,"(i) a clear and conspicuous disclosure has been made in writing to the consumer at any time before the report is procured or caused to be procured, in a document that consists solely of the disclosure, that a consumer report may be obtained for employment purposes; and"],[3,"(ii) the consumer has authorized in writing (which authorization may be made on the document referred to in clause (i)) the procurement of the report by that person."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, at any time before a consumer report is procured or caused to be procured in connection with that application—"],[3,"(i) the person who procures the consumer report on the consumer for employment purposes shall provide to the consumer, by oral, written, or electronic means, notice that a consumer report may be obtained for employment purposes, and a summary of the consumer's rights under section 1681m(a)(3) 1 of this title; and"],[3,"(ii) the consumer shall have consented, orally, in writing, or electronically to the procurement of the report by that person."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"],[3,"(i) the consumer is applying for a position over which the Secretary of Transportation has the power to establish qualifications and maximum hours of service pursuant to the provisions of section 31502 of title 49, or a position subject to safety regulation by a State transportation agency; and"],[3,"(ii) as of the time at which the person procures the report or causes the report to be procured the only interaction between the consumer and the person in connection with that employment application has been by mail, telephone, computer, or other similar means."],[0,"(3) Conditions on use for adverse actions"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), in using a consumer report for employment purposes, before taking any adverse action based in whole or in part on the report, the person intending to take such adverse action shall provide to the consumer to whom the report relates—"],[3,"(i) a copy of the report; and"],[3,"(ii) a description in writing of the rights of the consumer under this subchapter, as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(B) Application by mail, telephone, computer, or other similar means"],[2,"(i) If a consumer described in subparagraph (C) applies for employment by mail, telephone, computer, or other similar means, and if a person who has procured a consumer report on the consumer for employment purposes takes adverse action on the employment application based in whole or in part on the report, then the person must provide to the consumer to whom the report relates, in lieu of the notices required under subparagraph (A) of this section and under section 1681m(a) of this title, within 3 business days of taking such action, an oral, written or electronic notification—"],[3,"(I) that adverse action has been taken based in whole or in part on a consumer report received from a consumer reporting agency;"],[3,"(II) of the name, address and telephone number of the consumer reporting agency that furnished the consumer report (including a toll-free telephone number established by the agency if the agency compiles and maintains files on consumers on a nationwide basis);"],[3,"(III) that the consumer reporting agency did not make the decision to take the adverse action and is unable to provide to the consumer the specific reasons why the adverse action was taken; and"],[3,"(IV) that the consumer may, upon providing proper identification, request a free copy of a report and may dispute with the consumer reporting agency the accuracy or completeness of any information in a report."],[2,"(ii) If, under clause (B)(i)(IV), the consumer requests a copy of a consumer report from the person who procured the report, then, within 3 business days of receiving the consumer's request, together with proper identification, the person must send or provide to the consumer a copy of a report and a copy of the consumer's rights as prescribed by the Bureau under section 1681g(c)(3) 1 of this title."],[0,"(C) Scope"],[2,"Subparagraph (B) shall apply to a person procuring a consumer report on a consumer in connection with the consumer's application for employment only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681b?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1681b. Permissible purposes of consumer reports","tname":"Commerce and Trade","by":{"0":"5, 25, 4","1":"17, 2, 15, 16, 16, 16, 26"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)"],"by":{"0":"5","1":"3"}},{"t":"usc","label":"15 U.S.C. § 1681s","url":"https://www.law.cornell.edu/uscode/text/15/1681s","subs":["(a)(2)","(c)","(b)(1)(H)","(a)","(a)(2)(C)","(c)(1)(B)","(c)(5)"],"stext":{"head":"§1681s. Administrative enforcement","paras":[[0,"(a) Enforcement by Federal Trade Commission"],[0,"(1) In general"],[1,"The Federal Trade Commission shall be authorized to enforce compliance with the requirements imposed by this subchapter under the Federal Trade Commission Act (15 U.S.C. 41 et seq.), with respect to consumer reporting agencies and all other persons subject thereto, except to the extent that enforcement of the requirements imposed under this subchapter is specifically committed to some other Government agency under any of subparagraphs (A) through (G) of subsection (b)(1), and subject to subtitle B of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5511 et seq.], subsection (b).1 For the purpose of the exercise by the Federal Trade Commission of its functions and powers under the Federal Trade Commission Act, a violation of any requirement or prohibition imposed under this subchapter shall constitute an unfair or deceptive act or practice in commerce, in violation of section 5(a) of the Federal Trade Commission Act (15 U.S.C. 45(a)), and shall be subject to enforcement by the Federal Trade Commission under section 5(b) of that Act [15 U.S.C. 45(b)] with respect to any consumer reporting agency or person that is subject to enforcement by the Federal Trade Commission pursuant to this subsection, irrespective of whether that person is engaged in commerce or meets any other jurisdictional tests under the Federal Trade Commission Act. The Federal Trade Commission shall have such procedural, investigative, and enforcement powers, including the power to issue procedural rules in enforcing compliance with the requirements imposed under this subchapter and to require the filing of reports, the production of documents, and the appearance of witnesses, as though the applicable terms and conditions of the Federal Trade Commission Act were part of this subchapter. Any person violating any of the provisions of this subchapter shall be subject to the penalties and entitled to the privileges and immunities provided in the Federal Trade Commission Act as though the applicable terms and provisions of such Act are part of this subchapter."],[0,"(2) Penalties"],[0,"(A) Knowing violations"],[2,"Except as otherwise provided by subtitle B of the Consumer Financial Protection Act of 2010, in the event of a knowing violation, which constitutes a pattern or practice of violations of this subchapter, the Federal Trade Commission may commence a civil action to recover a civil penalty in a district court of the United States against any person that violates this subchapter. In such action, such person shall be liable for a civil penalty of not more than $2,500 per violation."],[0,"(B) Determining penalty amount"],[2,"In determining the amount of a civil penalty under subparagraph (A), the court shall take into account the degree of culpability, any history of such prior conduct, ability to pay, effect on ability to continue to do business, and such other matters as justice may require."],[0,"(C) Limitation"],[2,"Notwithstanding paragraph (2), a court may not impose any civil penalty on a person for a violation of section 1681s–2(a)(1) of this title, unless the person has been enjoined from committing the violation, or ordered not to commit the violation, in an action or proceeding brought by or on behalf of the Federal Trade Commission, and has violated the injunction or order, and the court may not impose any civil penalty for any violation occurring before the date of the violation of the injunction or order."],[0,"(b) Enforcement by other agencies"],[0,"(1) In general"],[1,"Subject to subtitle B of the Consumer Financial Protection Act of 2010, compliance with the requirements imposed under this subchapter with respect to consumer reporting agencies, persons who use consumer reports from such agencies, persons who furnish information to such agencies, and users of information that are subject to section 1681m(d) of this title shall be enforced under—"],[2,"(A) section 8 of the Federal Deposit Insurance Act (12 U.S.C. 1818), by the appropriate Federal banking agency, as defined in section 3(q) of the Federal Deposit Insurance Act (12 U.S.C. 1813(q)), with respect to—"],[3,"(i) any national bank or State savings association, and any Federal branch or Federal agency of a foreign bank;"],[3,"(ii) any member bank of the Federal Reserve System (other than a national bank), a branch or agency of a foreign bank (other than a Federal branch, Federal agency, or insured State branch of a foreign bank), a commercial lending company owned or controlled by a foreign bank, and any organization operating under section 25 or 25A of the Federal Reserve Act [12 U.S.C. 601 et seq., 611 et seq.]; and"],[3,"(iii) any bank or Federal savings association insured by the Federal Deposit Insurance Corporation (other than a member of the Federal Reserve System) and any insured State branch of a foreign bank;"],[2,"(B) the Federal Credit Union Act (12 U.S.C. 1751 et seq.), by the Administrator of the National Credit Union Administration with respect to any Federal credit union;"],[2,"(C) subtitle IV of title 49, by the Secretary of Transportation, with respect to all carriers subject to the jurisdiction of the Surface Transportation Board;"],[2,"(D) part A of subtitle VII of title 49, by the Secretary of Transportation, with respect to any air carrier or foreign air carrier subject to that part;"],[2,"(E) the Packers and Stockyards Act, 1921 (7 U.S.C. 181 et seq.) (except as provided in section 406 of that Act [7 U.S.C. 226, 227]), by the Secretary of Agriculture, with respect to any activities subject to that Act;"],[2,"(F) the Commodity Exchange Act [7 U.S.C. 1 et seq.], with respect to a person subject to the jurisdiction of the Commodity Futures Trading Commission;"],[2,"(G) the Federal securities laws, and any other laws that are subject to the jurisdiction of the Securities and Exchange Commission, with respect to a person that is subject to the jurisdiction of the Securities and Exchange Commission; and"],[2,"(H) subtitle E of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5561 et seq.], by the Bureau, with respect to any person subject to this subchapter."],[0,"(2) Incorporated definitions"],[1,"The terms used in paragraph (1) that are not defined in this subchapter or otherwise defined in section 3(s) of the Federal Deposit Insurance Act (12 U.S.C. 1813(s)) have the same meanings as in section 1(b) of the International Banking Act of 1978 (12 U.S.C. 3101)."],[0,"(c) State action for violations"],[0,"(1) Authority of States"],[1,"In addition to such other remedies as are provided under State law, if the chief law enforcement officer of a State, or an official or agency designated by a State, has reason to believe that any person has violated or is violating this subchapter, the State—"],[2,"(A) may bring an action to enjoin such violation in any appropriate United States district court or in any other court of competent jurisdiction;"],[2,"(B) subject to paragraph (5), may bring an action on behalf of the residents of the State to recover—"],[3,"(i) damages for which the person is liable to such residents under sections 1681n and 1681o of this title as a result of the violation;"],[3,"(ii) in the case of a violation described in any of paragraphs (1) through (3) of section 1681s–2(c) of this title, damages for which the person would, but for section 1681s–2(c) of this title, be liable to such residents as a result of the violation; or"],[3,"(iii) damages of not more than $1,000 for each willful or negligent violation; and"],[2,"(C) in the case of any successful action under subparagraph (A) or (B), shall be awarded the costs of the action and reasonable attorney fees as determined by the court."],[0,"(2) Rights of Federal regulators"],[1,"The State shall serve prior written notice of any action under paragraph (1) upon the Bureau and the Federal Trade Commission or the appropriate Federal regulator determined under subsection (b) and provide the Bureau and the Federal Trade Commission or appropriate Federal regulator with a copy of its complaint, except in any case in which such prior notice is not feasible, in which case the State shall serve such notice immediately upon instituting such action. The Bureau and the Federal Trade Commission or appropriate Federal regulator shall have the right—"],[2,"(A) to intervene in the action;"],[2,"(B) upon so intervening, to be heard on all matters arising therein;"],[2,"(C) to remove the action to the appropriate United States district court; and"],[2,"(D) to file petitions for appeal."],[0,"(3) Investigatory powers"],[1,"For purposes of bringing any action under this subsection, nothing in this subsection shall prevent the chief law enforcement officer, or an official or agency designated by a State, from exercising the powers conferred on the chief law enforcement officer or such official by the laws of such State to conduct investigations or to administer oaths or affirmations or to compel the attendance of witnesses or the production of documentary and other evidence."],[0,"(4) Limitation on State action while Federal action pending"],[1,"If the Bureau, the Federal Trade Commission, or the appropriate Federal regulator has instituted a civil action or an administrative action under section 8 of the Federal Deposit Insurance Act [12 U.S.C. 1818] for a violation of this subchapter, no State may, during the pendency of such action, bring an action under this section against any defendant named in the complaint of the Bureau, the Federal Trade Commission, or the appropriate Federal regulator for any violation of this subchapter that is alleged in that complaint."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681s?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1681s. Administrative enforcement","tname":"Commerce and Trade","by":{"0":"5, 5, 5, 5","1":"3, 9, 24, 25, 26, 4, 21, 22, 24, 24, 4, 21, 22, 24, 25, 26, 25, 24"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"0":"29","1":"20"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","subs":["(b)","(a)(1)"],"stext":{"head":"§1681. Congressional findings and statement of purpose","paras":[[0,"(a) Accuracy and fairness of credit reporting"],[0,"The Congress makes the following findings:"],[0,"(1) The banking system is dependent upon fair and accurate credit reporting. Inaccurate credit reports directly impair the efficiency of the banking system, and unfair credit reporting methods undermine the public confidence which is essential to the continued functioning of the banking system."],[0,"(2) An elaborate mechanism has been developed for investigating and evaluating the credit worthiness, credit standing, credit capacity, character, and general reputation of consumers."],[0,"(3) Consumer reporting agencies have assumed a vital role in assembling and evaluating consumer credit and other information on consumers."],[0,"(4) There is a need to insure that consumer reporting agencies exercise their grave responsibilities with fairness, impartiality, and a respect for the consumer's right to privacy."],[0,"(b) Reasonable procedures"],[0,"It is the purpose of this subchapter to require that consumer reporting agencies adopt reasonable procedures for meeting the needs of commerce for consumer credit, personnel, insurance, and other information in a manner which is fair and equitable to the consumer, with regard to the confidentiality, accuracy, relevancy, and proper utilization of such information in accordance with the requirements of this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681?type=usc&year=mostrecent&link-type=html"},"head":"§1681. Congressional findings and statement of purpose","tname":"Commerce and Trade","by":{"0":"3, 2","1":"35","2":"1"}},{"t":"usc","label":"15 U.S.C. § 1681a","url":"https://www.law.cornell.edu/uscode/text/15/1681a","subs":["(b)(1970)","(a)","(b)","(f)","(o)(2)(B)"],"stext":{"head":"§1681a. Definitions; rules of construction","paras":[[0,"(a) Definitions and rules of construction set forth in this section are applicable for the purposes of this subchapter."],[0,"(b) The term \"person\" means any individual, partnership, corporation, trust, estate, cooperative, association, government or governmental subdivision or agency, or other entity."],[0,"(c) The term \"consumer\" means an individual."],[0,"(d) Consumer Report.—"],[1,"(1) In general.—The term \"consumer report\" means any written, oral, or other communication of any information by a consumer reporting agency bearing on a consumer's credit worthiness, credit standing, credit capacity, character, general reputation, personal characteristics, or mode of living which is used or expected to be used or collected in whole or in part for the purpose of serving as a factor in establishing the consumer's eligibility for—"],[2,"(A) credit or insurance to be used primarily for personal, family, or household purposes;"],[2,"(B) employment purposes; or"],[2,"(C) any other purpose authorized under section 1681b of this title."],[1,"(2) Exclusions.—Except as provided in paragraph (3), the term \"consumer report\" does not include—"],[2,"(A) subject to section 1681s–3 of this title, any—"],[3,"(i) report containing information solely as to transactions or experiences between the consumer and the person making the report;"],[3,"(ii) communication of that information among persons related by common ownership or affiliated by corporate control; or"],[3,"(iii) communication of other information among persons related by common ownership or affiliated by corporate control, if it is clearly and conspicuously disclosed to the consumer that the information may be communicated among such persons and the consumer is given the opportunity, before the time that the information is initially communicated, to direct that such information not be communicated among such persons;"],[2,"(B) any authorization or approval of a specific extension of credit directly or indirectly by the issuer of a credit card or similar device;"],[2,"(C) any report in which a person who has been requested by a third party to make a specific extension of credit directly or indirectly to a consumer conveys his or her decision with respect to such request, if the third party advises the consumer of the name and address of the person to whom the request was made, and such person makes the disclosures to the consumer required under section 1681m of this title; or"],[2,"(D) a communication described in subsection (o) or (x).1"],[1,"(3) Restriction on sharing of medical information.—Except for information or any communication of information disclosed as provided in section 1681b(g)(3) of this title, the exclusions in paragraph (2) shall not apply with respect to information disclosed to any person related by common ownership or affiliated by corporate control, if the information is—"],[2,"(A) medical information;"],[2,"(B) an individualized list or description based on the payment transactions of the consumer for medical products or services; or"],[2,"(C) an aggregate list of identified consumers based on payment transactions for medical products or services."],[0,"(e) The term \"investigative consumer report\" means a consumer report or portion thereof in which information on a consumer's character, general reputation, personal characteristics, or mode of living is obtained through personal interviews with neighbors, friends, or associates of the consumer reported on or with others with whom he is acquainted or who may have knowledge concerning any such items of information. However, such information shall not include specific factual information on a consumer's credit record obtained directly from a creditor of the consumer or from a consumer reporting agency when such information was obtained directly from a creditor of the consumer or from the consumer."],[0,"(f) The term \"consumer reporting agency\" means any person which, for monetary fees, dues, or on a cooperative nonprofit basis, regularly engages in whole or in part in the practice of assembling or evaluating consumer credit information or other information on consumers for the purpose of furnishing consumer reports to third parties, and which uses any means or facility of interstate commerce for the purpose of preparing or furnishing consumer reports."],[0,"(g) The term \"file\", when used in connection with information on any consumer, means all of the information on that consumer recorded and retained by a consumer reporting agency regardless of how the information is stored."],[0,"(h) The term \"employment purposes\" when used in connection with a consumer report means a report used for the purpose of evaluating a consumer for employment, promotion, reassignment or retention as an employee."],[0,"(i) Medical Information.—The term \"medical information\"—"],[1,"(1) means information or data, whether oral or recorded, in any form or medium, created by or derived from a health care provider or the consumer, that relates to—"],[2,"(A) the past, present, or future physical, mental, or behavioral health or condition of an individual;"],[2,"(B) the provision of health care to an individual; or"],[2,"(C) the payment for the provision of health care to an individual.2"],[1,"(2) does not include the age or gender of a consumer, demographic information about the consumer, including a consumer's residence address or e-mail address, or any other information about a consumer that does not relate to the physical, mental, or behavioral health or condition of a consumer, including the existence or value of any insurance policy."],[0,"(j) Definitions Relating to Child Support Obligations.—"],[1,"(1) Overdue support.—The term \"overdue support\" has the meaning given to such term in section 666(e) of title 42."],[1,"(2) State or local child support enforcement agency.—The term \"State or local child support enforcement agency\" means a State or local agency which administers a State or local program for establishing and enforcing child support obligations."],[0,"(k) Adverse Action.—"],[1,"(1) Actions included.—The term \"adverse action\"—"],[2,"(A) has the same meaning as in section 1691(d)(6) of this title; and"],[2,"(B) means—"],[3,"(i) a denial or cancellation of, an increase in any charge for, or a reduction or other adverse or unfavorable change in the terms of coverage or amount of, any insurance, existing or applied for, in connection with the underwriting of insurance;"],[3,"(ii) a denial of employment or any other decision for employment purposes that adversely affects any current or prospective employee;"],[3,"(iii) a denial or cancellation of, an increase in any charge for, or any other adverse or unfavorable change in the terms of, any license or benefit described in section 1681b(a)(3)(D) of this title; and"],[3,"(iv) an action taken or determination that is—"],[4,"(I) made in connection with an application that was made by, or a transaction that was initiated by, any consumer, or in connection with a review of an account under section 1681b(a)(3)(F)(ii) of this title; and"],[4,"(II) adverse to the interests of the consumer."],[1,"(2) Applicable findings, decisions, commentary, and orders.—For purposes of any determination of whether an action is an adverse action under paragraph (1)(A), all appropriate final findings, decisions, commentary, and orders issued under section 1691(d)(6) of this title by the Bureau or any court shall apply."],[0,"(l) Firm Offer of Credit or Insurance.—The term \"firm offer of credit or insurance\" means any offer of credit or insurance to a consumer that will be honored if the consumer is determined, based on information in a consumer report on the consumer, to meet the specific criteria used to select the consumer for the offer, except that the offer may be further conditioned on one or more of the following:"],[1,"(1) The consumer being determined, based on information in the consumer's application for the credit or insurance, to meet specific criteria bearing on credit worthiness or insurability, as applicable, that are established—"],[2,"(A) before selection of the consumer for the offer; and"],[2,"(B) for the purpose of determining whether to extend credit or insurance pursuant to the offer."],[1,"(2) Verification—"],[2,"(A) that the consumer continues to meet the specific criteria used to select the consumer for the offer, by using information in a consumer report on the consumer, information in the consumer's application for the credit or insurance, or other information bearing on the credit worthiness or insurability of the consumer; or"],[2,"(B) of the information in the consumer's application for the credit or insurance, to determine that the consumer meets the specific criteria bearing on credit worthiness or insurability."],[1,"(3) The consumer furnishing any collateral that is a requirement for the extension of the credit or insurance that was—"],[2,"(A) established before selection of the consumer for the offer of credit or insurance; and"],[2,"(B) disclosed to the consumer in the offer of credit or insurance."],[0,"(m) Credit or Insurance Transaction That Is Not Initiated by the Consumer.—The term \"credit or insurance transaction that is not initiated by the consumer\" does not include the use of a consumer report by a person with which the consumer has an account or insurance policy, for purposes of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681a?type=usc&year=mostrecent&link-type=html"},"op":13,"head":"§1681a. Definitions; rules of construction","tname":"Commerce and Trade","by":{"0":"3, 18, 25, 25","1":"3, 14, 1, 3, 5, 8, 12, 14, 2, 15"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(1970)","(a)(1)(A)","(a)(1)(B)","(a)","(a)(1)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":1,"head":"§1681n. Civil liability for willful noncompliance","tname":"Commerce and Trade","by":{"0":"2, 5, 5","1":"1, 4, 9, 12, 14, 15","2":"2, 4, 10, 13, 14, 16-20, 22, 17, 21"}},{"t":"usc","label":"15 U.S.C. § 1681o","url":"https://www.law.cornell.edu/uscode/text/15/1681o","subs":["(1970)","(a)"],"stext":{"head":"§1681o. Civil liability for negligent noncompliance","paras":[[0,"(a) In general"],[0,"Any person who is negligent in failing to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1) any actual damages sustained by the consumer as a result of the failure; and"],[1,"(2) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Attorney's fees"],[0,"On a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681o?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681o. Civil liability for negligent noncompliance","tname":"Commerce and Trade","by":{"0":"2, 5","1":"1, 4, 9, 12, 14","2":"2, 4, 10, 13, 14, 16-20, 22, 17, 21"}},{"t":"usc","label":"15 U.S.C. § 1681q","url":"https://www.law.cornell.edu/uscode/text/15/1681q","subs":["(1970)"],"stext":{"head":"§1681q. Obtaining information under false pretenses","paras":[[0,"Any person who knowingly and willfully obtains information on a consumer from a consumer reporting agency under false pretenses shall be fined under title 18, imprisoned for not more than 2 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681q?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1681q. Obtaining information under false pretenses","tname":"Commerce and Trade","by":{"0":"2, 5","1":"3, 9, 21–24","2":"14-17, 19"}},{"t":"usc","label":"15 U.S.C. § 1681r","url":"https://www.law.cornell.edu/uscode/text/15/1681r","subs":["(1970)"],"by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 1681d","url":"https://www.law.cornell.edu/uscode/text/15/1681d","subs":["(a)"],"by":{"0":"3, 4","1":"3"}},{"t":"usc","label":"15 U.S.C. § 1681k","url":"https://www.law.cornell.edu/uscode/text/15/1681k","subs":["(a)(1)","(b)"],"by":{"0":"25, 4, 29, 29","1":"16"}},{"t":"usc","label":"15 U.S.C. § 1681s-2","url":"https://www.law.cornell.edu/uscode/text/15/1681s-2","subs":["(b)","(b)(1)","(a)","(a)(1)","(c)","(d)"],"by":{"0":"36, 37, 4, 6","1":"3, 5, 19, 25, 26, 4, 24, 25, 24, 1, 4, 4, 4, 25"}},{"t":"usc","label":"15 U.S.C. § 1681u","url":"https://www.law.cornell.edu/uscode/text/15/1681u","subs":["(a)","(g)","(j)","(l)","(m)"],"stext":{"head":"§1681u. Disclosures to FBI for counterintelligence purposes","paras":[[0,"(a) Identity of financial institutions"],[0,"Notwithstanding section 1681b of this title or any other provision of this subchapter, a consumer reporting agency shall furnish to the Federal Bureau of Investigation the names and addresses of all financial institutions (as that term is defined in section 3401 of title 12) at which a consumer maintains or has maintained an account, to the extent that information is in the files of the agency, when presented with a written request for that information that includes a term that specifically identifies a consumer or account to be used as the basis for the production of that information, signed by the Director of the Federal Bureau of Investigation, or the Director's designee in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office designated by the Director, which certifies compliance with this section. The Director or the Director's designee may make such a certification only if the Director or the Director's designee has determined in writing, that such information is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States."],[0,"(b) Identifying information"],[0,"Notwithstanding the provisions of section 1681b of this title or any other provision of this subchapter, a consumer reporting agency shall furnish identifying information respecting a consumer, limited to name, address, former addresses, places of employment, or former places of employment, to the Federal Bureau of Investigation when presented with a written request that includes a term that specifically identifies a consumer or account to be used as the basis for the production of that information, signed by the Director or the Director's designee in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office designated by the Director, which certifies compliance with this subsection. The Director or the Director's designee may make such a certification only if the Director or the Director's designee has determined in writing that such information is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States."],[0,"(c) Court order for disclosure of consumer reports"],[0,"Notwithstanding section 1681b of this title or any other provision of this subchapter, if requested in writing by the Director of the Federal Bureau of Investigation, or a designee of the Director in a position not lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge in a Bureau field office designated by the Director, a court may issue an order ex parte, which shall include a term that specifically identifies a consumer or account to be used as the basis for the production of the information, directing a consumer reporting agency to furnish a consumer report to the Federal Bureau of Investigation, upon a showing in camera that the consumer report is sought for the conduct of an authorized investigation to protect against international terrorism or clandestine intelligence activities, provided that such an investigation of a United States person is not conducted solely upon the basis of activities protected by the first amendment to the Constitution of the United States. The terms of an order issued under this subsection shall not disclose that the order is issued for purposes of a counterintelligence investigation."],[0,"(d) Prohibition of certain disclosure"],[0,"(1) Prohibition"],[0,"(A) In general"],[2,"If a certification is issued under subparagraph (B) and notice of the right to judicial review under subsection (e) is provided, no consumer reporting agency that receives a request under subsection (a) or (b) or an order under subsection (c), or officer, employee, or agent thereof, shall disclose or specify in any consumer report, that the Federal Bureau of Investigation has sought or obtained access to information or records under subsection (a), (b), or (c)."],[0,"(B) Certification"],[2,"The requirements of subparagraph (A) shall apply if the Director of the Federal Bureau of Investigation, or a designee of the Director whose rank shall be no lower than Deputy Assistant Director at Bureau headquarters or a Special Agent in Charge of a Bureau field office, certifies that the absence of a prohibition of disclosure under this subsection may result in—"],[3,"(i) a danger to the national security of the United States;"],[3,"(ii) interference with a criminal, counterterrorism, or counterintelligence investigation;"],[3,"(iii) interference with diplomatic relations; or"],[3,"(iv) danger to the life or physical safety of any person."],[0,"(2) Exception"],[0,"(A) In general"],[2,"A consumer reporting agency that receives a request under subsection (a) or (b) or an order under subsection (c), or officer, employee, or agent thereof, may disclose information otherwise subject to any applicable nondisclosure requirement to—"],[3,"(i) those persons to whom disclosure is necessary in order to comply with the request;"],[3,"(ii) an attorney in order to obtain legal advice or assistance regarding the request; or"],[3,"(iii) other persons as permitted by the Director of the Federal Bureau of Investigation or the designee of the Director."],[0,"(B) Application"],[2,"A person to whom disclosure is made under subparagraph (A) shall be subject to the nondisclosure requirements applicable to a person to whom a request under subsection (a) or (b) or an order under subsection (c) is issued in the same manner as the person to whom the request is issued."],[0,"(C) Notice"],[2,"Any recipient that discloses to a person described in subparagraph (A) information otherwise subject to a nondisclosure requirement shall inform the person of the applicable nondisclosure requirement."],[0,"(D) Identification of disclosure recipients"],[2,"At the request of the Director of the Federal Bureau of Investigation or the designee of the Director, any person making or intending to make a disclosure under clause (i) or (iii) of subparagraph (A) shall identify to the Director or such designee the person to whom such disclosure will be made or to whom such disclosure was made prior to the request."],[0,"(e) Judicial review"],[0,"(1) In general"],[1,"A request under subsection (a) or (b) or an order under subsection (c) or a non-disclosure requirement imposed in connection with such request under subsection (d) shall be subject to judicial review under section 3511 of title 18."],[0,"(2) Notice"],[1,"A request under subsection (a) or (b) or an order under subsection (c) shall include notice of the availability of judicial review described in paragraph (1)."],[0,"(f) Payment of fees"],[0,"The Federal Bureau of Investigation shall, subject to the availability of appropriations, pay to the consumer reporting agency assembling or providing report or information in accordance with procedures established under this section a fee for reimbursement for such costs as are reasonably necessary and which have been directly incurred in searching, reproducing, or transporting books, papers, records, or other data required or requested to be produced under this section."],[0,"(g) Limit on dissemination"],[0,"The Federal Bureau of Investigation may not disseminate information obtained pursuant to this section outside of the Federal Bureau of Investigation, except to other Federal agencies as may be necessary for the approval or conduct of a foreign counterintelligence investigation, or, where the information concerns a person subject to the Uniform Code of Military Justice, to appropriate investigative authorities within the military department concerned as may be necessary for the conduct of a joint foreign counterintelligence investigation."],[0,"(h) Rules of construction"],[0,"Nothing in this section shall be construed to prohibit information from being furnished by the Federal Bureau of Investigation pursuant to a subpoena or court order, in connection with a judicial or administrative proceeding to enforce the provisions of this subchapter. Nothing in this section shall be construed to authorize or permit the withholding of information from the Congress."],[0,"(i) Reports to Congress"],[0,"(1) On a semiannual basis, the Attorney General shall fully inform the Permanent Select Committee on Intelligence and the Committee on Banking, Finance and Urban Affairs of the House of Representatives, and the Select Committee on Intelligence and the Committee on Banking, Housing, and Urban Affairs of the Senate concerning all requests made pursuant to subsections (a), (b), and (c)."],[0,"(2) In the case of the semiannual reports required to be submitted under paragraph (1) to the Permanent Select Committee on Intelligence of the House of Representatives and the Select Committee on Intelligence of the Senate, the submittal dates for such reports shall be as provided in section 3106 of title 50."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681u?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§1681u. Disclosures to FBI for counterintelligence purposes","tname":"Commerce and Trade","by":{"0":"25, 33","1":"7, 10, 11, 30, 31, 32, 17, 16, 29, 31, 29, 7, 10, 30, 31, 31, 31","2":"19, 20"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"25"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)(1970)","(b)(2000)","(b)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"head":"§216. Penalties","tname":"Labor","by":{"0":"25, 19","1":"39, 40","2":"6, 8, 9"}},{"t":"usc","label":"5 U.S.C. § 6381","url":"https://www.law.cornell.edu/uscode/text/5/6381","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","by":{"0":"5"}},{"t":"usc","label":"25 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/25/2710","subs":["(d)(7)(A)(i)"],"by":{"0":"18"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"0":"33"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","subs":["(a)"],"by":{"0":"17","2":"3"}},{"t":"usc","label":"33 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/33/1401","by":{"0":"23"}},{"t":"usc","label":"33 U.S.C. § 1402","url":"https://www.law.cornell.edu/uscode/text/33/1402","subs":["(e)"],"by":{"0":"23"}},{"t":"usc","label":"33 U.S.C. § 1415","url":"https://www.law.cornell.edu/uscode/text/33/1415","subs":["(g)(i)"],"by":{"0":"24"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(a)(1)","(b)","(c)(4)","(d)","(g)","(g)(1)(A)","(g)(2)(A)","(g)(4)(A)","(g)(1)(C)","(g)(1)(D)","(g)(4)"],"stext":{"head":"§552a. Records maintained on individuals","paras":[[0,"(a) Definitions.—For purposes of this section—"],[1,"(1) the term \"agency\" means agency as defined in section 552(e) 1 of this title;"],[1,"(2) the term \"individual\" means a citizen of the United States or an alien lawfully admitted for permanent residence;"],[1,"(3) the term \"maintain\" includes maintain, collect, use, or disseminate;"],[1,"(4) the term \"record\" means any item, collection, or grouping of information about an individual that is maintained by an agency, including, but not limited to, his education, financial transactions, medical history, and criminal or employment history and that contains his name, or the identifying number, symbol, or other identifying particular assigned to the individual, such as a finger or voice print or a photograph;"],[1,"(5) the term \"system of records\" means a group of any records under the control of any agency from which information is retrieved by the name of the individual or by some identifying number, symbol, or other identifying particular assigned to the individual;"],[1,"(6) the term \"statistical record\" means a record in a system of records maintained for statistical research or reporting purposes only and not used in whole or in part in making any determination about an identifiable individual, except as provided by section 8 of title 13;"],[1,"(7) the term \"routine use\" means, with respect to the disclosure of a record, the use of such record for a purpose which is compatible with the purpose for which it was collected;"],[1,"(8) the term \"matching program\"—"],[2,"(A) means any computerized comparison of—"],[3,"(i) two or more automated systems of records or a system of records with non-Federal records for the purpose of—"],[4,"(I) establishing or verifying the eligibility of, or continuing compliance with statutory and regulatory requirements by, applicants for, recipients or beneficiaries of, participants in, or providers of services with respect to, cash or in-kind assistance or payments under Federal benefit programs, or"],[4,"(II) recouping payments or delinquent debts under such Federal benefit programs, or"],[3,"(ii) two or more automated Federal personnel or payroll systems of records or a system of Federal personnel or payroll records with non-Federal records,"],[2,"(B) but does not include—"],[3,"(i) matches performed to produce aggregate statistical data without any personal identifiers;"],[3,"(ii) matches performed to support any research or statistical project, the specific data of which may not be used to make decisions concerning the rights, benefits, or privileges of specific individuals;"],[3,"(iii) matches performed, by an agency (or component thereof) which performs as its principal function any activity pertaining to the enforcement of criminal laws, subsequent to the initiation of a specific criminal or civil law enforcement investigation of a named person or persons for the purpose of gathering evidence against such person or persons;"],[3,"(iv) matches of tax information (I) pursuant to section 6103(d) of the Internal Revenue Code of 1986, (II) for purposes of tax administration as defined in section 6103(b)(4) of such Code, (III) for the purpose of intercepting a tax refund due an individual under authority granted by section 404(e), 464, or 1137 of the Social Security Act; or (IV) for the purpose of intercepting a tax refund due an individual under any other tax refund intercept program authorized by statute which has been determined by the Director of the Office of Management and Budget to contain verification, notice, and hearing requirements that are substantially similar to the procedures in section 1137 of the Social Security Act;"],[3,"(v) matches—"],[4,"(I) using records predominantly relating to Federal personnel, that are performed for routine administrative purposes (subject to guidance provided by the Director of the Office of Management and Budget pursuant to subsection (v)); or"],[4,"(II) conducted by an agency using only records from systems of records maintained by that agency;"],[0,"if the purpose of the match is not to take any adverse financial, personnel, disciplinary, or other adverse action against Federal personnel;"],[3,"(vi) matches performed for foreign counterintelligence purposes or to produce background checks for security clearances of Federal personnel or Federal contractor personnel;"],[3,"(vii) matches performed incident to a levy described in section 6103(k)(8) of the Internal Revenue Code of 1986;"],[3,"(viii) matches performed pursuant to section 202(x)(3) or 1611(e)(1) of the Social Security Act (42 U.S.C. 402(x)(3), 1382(e)(1));"],[3,"(ix) matches performed by the Secretary of Health and Human Services or the Inspector General of the Department of Health and Human Services with respect to potential fraud, waste, and abuse, including matches of a system of records with non-Federal records; or"],[3,"(x) matches performed pursuant to section 3(d)(4) of the Achieving a Better Life Experience Act of 2014; 1"],[1,"(9) the term \"recipient agency\" means any agency, or contractor thereof, receiving records contained in a system of records from a source agency for use in a matching program;"],[1,"(10) the term \"non-Federal agency\" means any State or local government, or agency thereof, which receives records contained in a system of records from a source agency for use in a matching program;"],[1,"(11) the term \"source agency\" means any agency which discloses records contained in a system of records to be used in a matching program, or any State or local government, or agency thereof, which discloses records to be used in a matching program;"],[1,"(12) the term \"Federal benefit program\" means any program administered or funded by the Federal Government, or by any agent or State on behalf of the Federal Government, providing cash or in-kind assistance in the form of payments, grants, loans, or loan guarantees to individuals; and"],[1,"(13) the term \"Federal personnel\" means officers and employees of the Government of the United States, members of the uniformed services (including members of the Reserve Components), individuals entitled to receive immediate or deferred retirement benefits under any retirement program of the Government of the United States (including survivor benefits)."],[0,"(b) Conditions of Disclosure.—No agency shall disclose any record which is contained in a system of records by any means of communication to any person, or to another agency, except pursuant to a written request by, or with the prior written consent of, the individual to whom the record pertains, unless disclosure of the record would be—"],[1,"(1) to those officers and employees of the agency which maintains the record who have a need for the record in the performance of their duties;"],[1,"(2) required under section 552 of this title;"],[1,"(3) for a routine use as defined in subsection (a)(7) of this section and described under subsection (e)(4)(D) of this section;"],[1,"(4) to the Bureau of the Census for purposes of planning or carrying out a census or survey or related activity pursuant to the provisions of title 13;"],[1,"(5) to a recipient who has provided the agency with advance adequate written assurance that the record will be used solely as a statistical research or reporting record, and the record is to be transferred in a form that is not individually identifiable;"],[1,"(6) to the National Archives and Records Administration as a record which has sufficient historical or other value to warrant its continued preservation by the United States Government, or for evaluation by the Archivist of the United States or the designee of the Archivist to determine whether the record has such value;"],[1,"(7) to another agency or to an instrumentality of any governmental jurisdiction within or under the control of the United States for a civil or criminal law enforcement activity if the activity is authorized by law, and if the head of the agency or instrumentality has made a written request to the agency which maintains the record specifying the particular portion desired and the law enforcement activity for which the record is sought;"],[1,"(8) to a person pursuant to a showing of compelling circumstances affecting the health or safety of an individual if upon such disclosure notification is transmitted to the last known address of such individual;"],[1,"(9) to either House of Congress, or, to the extent of matter within its jurisdiction, any committee or subcommittee thereof, any joint committee of Congress or subcommittee of any such joint committee;"],[1,"(10) to the Comptroller General, or any of his authorized representatives, in the course of the performance of the duties of the Government Accountability Office;"],[1,"(11) to the Director of the Congressional Budget Office, or any authorized representative of the Director, in the course of performance of the duties of the Congressional Budget Office;"],[1,"(12) pursuant to the order of a court of competent jurisdiction; or"],[1,"(13) to a consumer reporting agency in accordance with section 3711(e) of title 31."],[0,"(c) Accounting of Certain Disclosures.—Each agency, with respect to each system of records under its control, shall—"],[1,"(1) except for disclosures made under subsections (b)(1) or (b)(2) of this section, keep an accurate accounting of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§552a. Records maintained on individuals","tname":"Government Organization and Employees","by":{"0":"11, 36, 36, 36, 36, 20, 36, 37, 37, 37","1":"8, 31, 33, 33, 33, 33, 33, 34, 33, 34, 33, 33, 32","2":"3, 21, 21"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 6903","url":"https://www.law.cornell.edu/uscode/text/42/6903","subs":["(15)"],"by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(a)(1)(B)"],"by":{"0":"23"}},{"t":"usc","label":"7 U.S.C. § 6943","url":"https://www.law.cornell.edu/uscode/text/7/6943","by":{"0":"5"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)"],"stext":{"head":"§106. Waiver of sovereign immunity","paras":[[0,"(a) Notwithstanding an assertion of sovereign immunity, sovereign immunity is abrogated as to a governmental unit to the extent set forth in this section with respect to the following:"],[1,"(1) Sections 105, 106, 107, 108, 303, 346, 362, 363, 364, 365, 366, 502, 503, 505, 506, 510, 522, 523, 524, 525, 542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 722, 724, 726, 744, 749, 764, 901, 922, 926, 928, 929, 944, 1107, 1141, 1142, 1143, 1146, 1201, 1203, 1205, 1206, 1227, 1231, 1301, 1303, 1305, and 1327 of this title."],[1,"(2) The court may hear and determine any issue arising with respect to the application of such sections to governmental units."],[1,"(3) The court may issue against a governmental unit an order, process, or judgment under such sections or the Federal Rules of Bankruptcy Procedure, including an order or judgment awarding a money recovery, but not including an award of punitive damages. Such order or judgment for costs or fees under this title or the Federal Rules of Bankruptcy Procedure against any governmental unit shall be consistent with the provisions and limitations of section 2412(d)(2)(A) of title 28."],[1,"(4) The enforcement of any such order, process, or judgment against any governmental unit shall be consistent with appropriate nonbankruptcy law applicable to such governmental unit and, in the case of a money judgment against the United States, shall be paid as if it is a judgment rendered by a district court of the United States."],[1,"(5) Nothing in this section shall create any substantive claim for relief or cause of action not otherwise existing under this title, the Federal Rules of Bankruptcy Procedure, or nonbankruptcy law."],[0,"(b) A governmental unit that has filed a proof of claim in the case is deemed to have waived sovereign immunity with respect to a claim against such governmental unit that is property of the estate and that arose out of the same transaction or occurrence out of which the claim of such governmental unit arose."],[0,"(c) Notwithstanding any assertion of sovereign immunity by a governmental unit, there shall be offset against a claim or interest of a governmental unit any claim against such governmental unit that is property of the estate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/106?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§106. Waiver of sovereign immunity","tname":"Bankruptcy","by":{"0":"17"}},{"t":"usc","label":"17 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/17/511","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"20 U.S.C. § 1080a","url":"https://www.law.cornell.edu/uscode/text/20/1080a","by":{"0":"36"}},{"t":"usc","label":"20 U.S.C. § 1087a","url":"https://www.law.cornell.edu/uscode/text/20/1087a","subs":["(b)(2)"],"by":{"0":"36"}},{"t":"usc","label":"20 U.S.C. § 1087e","url":"https://www.law.cornell.edu/uscode/text/20/1087e","subs":["(a)(1)"],"by":{"0":"36"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)"],"by":{"0":"7, 20"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","subs":["(a)(2)(1982)","(a)(2)","(2)(1982)"],"by":{"0":"21, 21, 20","2":"5"}},{"t":"usc","label":"29 U.S.C. § 2611","url":"https://www.law.cornell.edu/uscode/text/29/2611","subs":["(4)(A)(iii)"],"by":{"0":"22"}},{"t":"usc","label":"29 U.S.C. § 2617","url":"https://www.law.cornell.edu/uscode/text/29/2617","subs":["(a)(2)"],"by":{"0":"19, 22","2":"8"}},{"t":"usc","label":"31 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/31/3711","subs":["(e)","(h)(2)"],"stext":{"head":"§3711. Collection and compromise","paras":[[0,"(a) The head of an executive, judicial, or legislative agency—"],[1,"(1) shall try to collect a claim of the United States Government for money or property arising out of the activities of, or referred to, the agency;"],[1,"(2) may compromise a claim of the Government of not more than $100,000 (excluding interest) or such higher amount as the Attorney General may from time to time prescribe that has not been referred to another executive or legislative agency for further collection action, except that only the Comptroller General may compromise a claim arising out of an exception the Comptroller General makes in the account of an accountable official; and"],[1,"(3) may suspend or end collection action on a claim referred to in clause (2) of this subsection when it appears that no person liable on the claim has the present or prospective ability to pay a significant amount of the claim or the cost of collecting the claim is likely to be more than the amount recovered."],[0,"(b)(1) The head of an executive, judicial, or legislative agency may not act under subsection (a)(2) or (3) of this section on a claim that appears to be fraudulent, false, or misrepresented by a party with an interest in the claim, or that is based on conduct in violation of the antitrust laws."],[0,"(2) The Secretary of Transportation may not compromise for less than $500 a penalty under section 21302 of title 49 for a violation of chapter 203, 205, or 207 of title 49 or a regulation or requirement prescribed or order issued under any of those chapters."],[0,"(c) A compromise under this section is final and conclusive unless gotten by fraud, misrepresentation, presenting a false claim, or mutual mistake of fact. An accountable official is not liable for an amount paid or for the value of property lost or damaged if the amount or value is not recovered because of a compromise under this section."],[0,"(d) The head of an executive, judicial, or legislative agency acts under—"],[1,"(1) regulations prescribed by the head of the agency; and"],[1,"(2) standards that the Attorney General, the Secretary of the Treasury, may prescribe.1"],[0,"(e)(1) When trying to collect a claim of the Government under a law except the Internal Revenue Code of 1986 (26 U.S.C. 1 et seq.), the head of an executive, judicial, or legislative agency shall disclose to a consumer reporting agency information from a system of records that a person is responsible for a claim if—"],[1,"(A) notice required by section 552a(e)(4) of title 5 indicates that information in the system may be disclosed to a consumer reporting agency;"],[1,"(B) the head of the agency has reviewed the claim and decided that the claim is valid and overdue;"],[1,"(C) the head of the agency has notified the person in writing—"],[2,"(i) that payment of the claim is overdue;"],[2,"(ii) that, within not less than 60 days after sending the notice, the head of the agency intends to disclose to a consumer reporting agency that the person is responsible for the claim;"],[2,"(iii) of the specific information to be disclosed to the consumer reporting agency; and"],[2,"(iv) of the rights the person has to a complete explanation of the claim, to dispute information in the records of the agency about the claim, and to administrative repeal or review of the claim;"],[1,"(D) the person has not—"],[2,"(i) repaid or agreed to repay the claim under a written repayment plan that the person has signed and the head of the agency has agreed to; or"],[2,"(ii) filed for review of the claim under paragraph (2) of this subsection;"],[1,"(E) the head of the agency has established procedures to—"],[2,"(i) disclose promptly, to each consumer reporting agency to which the original disclosure was made, a substantial change in the condition or amount of the claim;"],[2,"(ii) verify or correct promptly information about the claim on request of a consumer reporting agency for verification of information disclosed; and"],[2,"(iii) get satisfactory assurances from each consumer reporting agency that the agency is complying with all laws of the United States related to providing consumer credit information; and"],[1,"(F) the information disclosed to the consumer reporting agency is limited to—"],[2,"(i) information necessary to establish the identity of the person, including name, address, and taxpayer identification number;"],[2,"(ii) the amount, status, and history of the claim; and"],[2,"(iii) the agency or program under which the claim arose."],[0,"(2) Before disclosing information to a consumer reporting agency under paragraph (1) of this subsection and at other times allowed by law, the head of an executive, judicial, or legislative agency shall provide, on request of a person alleged by the agency to be responsible for the claim, for a review of the obligation of the person, including an opportunity for reconsideration of the initial decision on the claim."],[0,"(3) Before disclosing information to a consumer reporting agency under paragraph (1) of this subsection, the head of an executive, judicial, or legislative agency shall take reasonable action to locate a person for whom the head of the agency does not have a current address to send the notice under paragraph (1)(C)."],[0,"(4) The head of each executive agency shall require, as a condition for insuring or guaranteeing any loan, financing, or other extension of credit under any law to a person, that the lender provide information relating to the extension of credit to consumer reporting agencies or commercial reporting agencies, as appropriate."],[0,"(5) The head of each executive agency may provide to a consumer reporting agency or commercial reporting agency information from a system of records that a person is responsible for a claim which is current, if notice required by section 552a(e)(4) of title 5 indicates that information in the system may be disclosed to a consumer reporting agency or commercial reporting agency, respectively."],[0,"(f)(1) The Secretary of Defense may suspend or terminate an action by the Secretary or by the Secretary of a military department under subsection (a) to collect a claim against the estate of a person who died while serving on active duty as a member of the Army, Navy, Air Force, Marine Corps, Space Force, or Coast Guard during a period when the Coast Guard is operating as a service in the Navy if the Secretary determines that, under the circumstances applicable with respect to the deceased person, it is appropriate to do so."],[0,"(2) The Secretary of Homeland Security may suspend or terminate an action by the Secretary under subsection (a) to collect a claim against the estate of a person who died while serving on active duty as a member of the Coast Guard if the Secretary determines that, under the circumstances applicable with respect to the deceased person, it is appropriate to do so."],[0,"(3) The Secretary of Veterans Affairs may suspend or terminate an action by the Secretary under subsection (a) to collect a claim against the estate of a person who died while serving on active duty as a member of the Army, Navy, Air Force, Marine Corps, Space Force, or Coast Guard during a period when the Coast Guard is operating as a service in the Navy if the Secretary determines that, under the circumstances applicable with respect to the deceased person, it is appropriate to do so."],[0,"(4) In this subsection, the term \"active duty\" has the meaning given that term in section 101 of title 10."],[0,"(g)(1) If a nontax debt or claim owed to the United States has been delinquent for a period of 180 days—"],[1,"(A) the head of the executive, judicial, or legislative agency that administers the program that gave rise to the debt or claim shall transfer the debt or claim to the Secretary of the Treasury; and"],[1,"(B) upon such transfer the Secretary of the Treasury shall take appropriate action to collect or terminate collection actions on the debt or claim."],[0,"(2) Paragraph (1) shall not apply—"],[1,"(A) to any debt or claim that—"],[2,"(i) is in litigation or foreclosure;"],[2,"(ii) will be disposed of under an asset sales program within 1 year after becoming eligible for sale, or later than 1 year if consistent with an asset sales program and a schedule established by the agency and approved by the Director of the Office of Management and Budget;"],[2,"(iii) has been referred to a private collection contractor for collection for a period of time determined by the Secretary of the Treasury;"],[2,"(iv) has been referred by, or with the consent of, the Secretary of the Treasury to a debt collection center for a period of time determined by the Secretary of the Treasury; or"],[2,"(v) will be collected under internal offset, if such offset is sufficient to collect the claim within 3 years after the date the debt or claim is first delinquent; and"],[1,"(B) to any other specific class of debt or claim, as determined by the Secretary of the Treasury at the request of the head of an executive, judicial, or legislative agency or otherwise."],[0,"(3) For purposes of this section, the Secretary of the Treasury may designate, and withdraw such designation of debt collection centers operated by other Federal agencies. The Secretary of the Treasury shall designate such centers on the basis of their performance in collecting delinquent claims owed to the Government."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3711?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3711. Collection and compromise","tname":"Money and Finance","by":{"0":"36","1":"16","2":"20"}},{"t":"usc","label":"35 U.S.C. § 296","url":"https://www.law.cornell.edu/uscode/text/35/296","subs":["(a)"],"by":{"0":"17"}},{"t":"usc","label":"39 U.S.C. § 409","url":"https://www.law.cornell.edu/uscode/text/39/409","subs":["(d)(1)(A)","(d)(1)(B)"],"by":{"0":"14, 14","2":"3"}},{"t":"usc","label":"43 U.S.C. § 390uu","url":"https://www.law.cornell.edu/uscode/text/43/390uu","by":{"0":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(b)"],"by":{"0":"6"}},{"t":"case","label":"Abitron Austria GmbH v. Hetronic International, Inc.","cite":"600 U.S. 412","y":2023,"id":"2022/21-1043","sc":1,"sum":"Applying the presumption against extraterritoriality, two provisions of the Lanham Act that prohibit trademark infringement—15 U. S. C. §1114(1)(a) and §1125(a)(1)—are not extraterritorial and extend only to claims where the infringing “use in commerce” is domestic.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27, 28","2":"11"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"13, 22"}},{"t":"case","label":"Blatchford v. Native Village of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"1":"14, 19, 20"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"1":"13, 41"}},{"t":"case","label":"Chambers v. U.S. Department of Interior","cite":"568 F.3d 998","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/568/998/","by":{"1":"34"}},{"t":"case","label":"Coleman v. Court of Appeals of Md.","cite":"566 U.S. 30","y":2012,"id":"2011/10-1016","sc":1,"op":1,"sum":"The Court held that states have sovereign immunity to suits brought under the self-care provision of the Family and Medical Leave Act.","sumSrc":"Oyez","by":{"1":"40","2":"8, 9"}},{"t":"case","label":"College Savings Bank v. Florida Prepaid Postsecondary Educational Expense Board","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"op":4,"ar":3,"sum":"The Court held that \"the federal courts are without jurisdiction to entertain this suit against an arm of the State of Florida.\" Justice Scalia concluded that \"the sovereign immunity of the State of Florida was neither validly abrogated by the Trademark Remedy Clarification Act, nor voluntarily waived by the State's activities in interstate commerce.\" Writing for the dissenting minority, Justice Stephen G. Breyer expressed the view that Congress possesses the authority to abrogate a state's sovereign immunity where necessary and proper to the exercise of a congressional power under the Constitution's Article I. Justice John Paul Stevens filed his own dissenting opinion and joined that of Justice Breyer.","sumSrc":"Oyez","by":{"1":"43, 45, 46","2":"2, 4, 6, 7, 11"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Cook County v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"sum":"The Court held that the term \"person\" includes local governments. The Court noted that the County, as a recipient of federal funding, was clearly able to abuse federal spending and was thus subject to the FCA remedy that applied to prevent such abuse.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"op":2,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"14, 15, 19, 35"}},{"t":"case","label":"Eastern Transportation Co. v. United States","cite":"272 U.S. 675","y":1927,"id":"scdb/1926-107","sc":1,"sum":"1. Abandonment within the thirty day period set by the Act of March 3, 1899, will not be presumed of a wreck left in a navigable 5 So far as the record discloses, the stay included in the final decree was not a continuation of a temporary restraining order, but a matter wholly original. Apparently, no restraining order issued prior to the final decree. The matter is not referred to in any of the briefs. Argument for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"op":3,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Fourth Estate Public Benefit Corp. v. WallStreet.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"op":1,"sum":"Registration occurs, and a copyright claimant may commence an infringement suit, when the Copyright Office registers a copyright.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Fox v. Standard Oil Co. of New Jersey","cite":"294 U.S. 87","y":1935,"id":"scdb/1934-085","sc":1,"sum":"1. Filling stations and distribution plants where gasoline, other petroleum products, and automobile accessories are sold, are \"stores \" within the meaning of the West Virginia Chain Store License Tax Act, defining the term store as including any mercantile establishment in which goods, wares or merchandise of any kind are sold, etc.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Hamer v. Neighborhood Housing Services of Chicago","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"op":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Lawson v. Suwannee Fruit & Steamship Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"sum":"Under § 8 (f) (1) of the Act, the employer was liable only for permanent partial disability (loss of the left eye), and the remainder of the compensation due for permanent total disability was payable out of the special fund established by § 44 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37, 38"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Markham v. Cabell","cite":"326 U.S. 404","y":1945,"id":"scdb/1945-001","sc":1,"sum":"1. Section 9 (a) of the Trading with the Enemy Act allows \"Any person not an enemy or ally of enemy...to whom any debt may be owing from an enemy or ally of enemy whose property or any part thereof shall have been conveyed, transferred, assigned, delivered, or paid to the Alien Property Custodian\" to sue the Custodian or the Treasurer of the United States in the federal courts. Section 9 (e) provides that no debt …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Moore v. U.S. Department of Agriculture","cite":"55 F.3d 991","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/991/","by":{"1":"18"}},{"t":"case","label":"Mowrer v. U.S. Department of Transportation","cite":"14 F.4th 723","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/14/723/","ar":1,"by":{"1":"22"}},{"t":"case","label":"Newport v. Fact Concerts, Inc.","cite":"453 U.S. 247","y":1981,"id":"1980/80-396","sc":1,"sum":"Respondents (an organization licensed by petitioner city to present certain musical concerts, and a promoter of the concerts) brought suit in Federal District Court against the city and city officials. Alleging, inter alia, that the city's cancellation of the license amounted to a violation of their constitutional rights under color of.state law, repondents sought compensatory and punitive damages under 42 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"Parden v. Terminal Railway Co. of Alaska Docks Department","cite":"377 U.S. 184","y":1964,"id":"1963/157","sc":1,"op":10,"ar":4,"sum":"Operation of a common carrier railroad in interstate commerce by a State constituted a waiver of its sovereign immunity and consent to a suit brought in a federal court by employees of the railroad under the Federal Employers' Liability Act. Pp. 184-198. 311 F. 2d 727, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43, 46","2":"7, 13"}},{"t":"case","label":"Pennhurst State School and Hospital v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46","2":"13"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"op":3,"sum":"Rejecting the use of legislative history when assessing whether Congress abrogated sovereign immunity.","sumSrc":"opinion","by":{"1":"30, 43, 46, 47","2":"7"}},{"t":"case","label":"Phillips v. Grendahl","cite":"312 F.3d 357","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/312/357/","by":{"1":"24"}},{"t":"case","label":"Richlin Security Service Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"sum":"The Court held that such paralegal fees are recoverable at market rates. Justice Samuel A. Alito stated that because Richlin incurred fees for paralegal services in connection with its case, a straightforward reading of the statute demonstrates that Richlin was entitled to recover fees for the paralegal services it purchased at the market rate.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"1":"21","2":"16, 17"}},{"t":"case","label":"Rowland v. California Men’s Colony, Unit II Men’s Advisory Council","cite":"506 U.S. 194","y":1993,"id":"1992/91-1188","sc":1,"sum":"In a suit filed in the District Court against petitioner state correctional officers, respondent, a representative association of inmates in a California prison, sought leave to proceed in forma pauperis under 28 U. S. C. § 1915(a), which permits litigation without prepayment of fees, costs, or security \"by a person who makes affidavit that he is unable to pay.\" The court denied the motion for an inadequate showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Safeco Insurance Co. of America v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"op":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"1":"2, 24"}},{"t":"case","label":"SAS Institute, Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"op":1,"ar":1,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20, 21"}},{"t":"case","label":"Torres v. Texas Department of Public Safety","cite":"142 S. Ct. 2455","y":2022,"id":"2021/20-603","sc":1,"sum":"By ratifying the Constitution, the States agreed their sovereignty would yield to the national power to raise and support the Armed Forces; Congress may exercise this power to authorize private damages suits against nonconsenting States, as in the Uniformed Services Employment and Reemployment Rights Act of 1994.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Türkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"op":3,"ar":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"U.S. Postal Service v. Flamingo Industries (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"sum":"The Court held that the U.S. Postal Service cannot be sued under antitrust laws. The Court acknowledged the Postal Reorganization Act may waive the Postal Service's immunity from suit. However, federal antitrust laws (the Sherman Act, for example) do not allow the federal government - of which the Postal Service is a part - to be sued.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Welch v. Texas Department of Highways and Public Transportation","cite":"483 U.S. 468","y":1987,"id":"1986/85-1716","sc":1,"op":1,"sum":"The judgment is affirmed. 780 F. 2d 1268, affirmed. JUSTICE POWELL, joined by THE CHIEF JUSTICE, JUSTICE WHITE, and JUSTICE O'CONNOR, concluded that the Eleventh Amendment bars a state employee from suing the State in federal court under the Jones Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43, 46"}},{"t":"usc","label":"15 U.S.C. § 1601-1693r","url":"https://www.law.cornell.edu/uscode/text/15/1601-1693r","by":{"1":"6, 17"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"45"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"33"}},{"t":"usc","label":"15 U.S.C. § 1691a","url":"https://www.law.cornell.edu/uscode/text/15/1691a","subs":["(e)","(f)"],"by":{"1":"6, 17, 17","2":"12, 12"}},{"t":"usc","label":"15 U.S.C. § 1691c","url":"https://www.law.cornell.edu/uscode/text/15/1691c","subs":["(a)(9)","(c)"],"by":{"1":"25, 25"}},{"t":"usc","label":"15 U.S.C. § 1691e","url":"https://www.law.cornell.edu/uscode/text/15/1691e","subs":["(a)","(b)"],"by":{"1":"17, 6, 17","2":"12, 12"}},{"t":"law","label":"Fair Credit Reporting Act, Pub. L. No. 91-508","url":"https://www.govinfo.gov/link/statute/84/1127","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 1681c-1","url":"https://www.law.cornell.edu/uscode/text/15/1681c-1","subs":["(i)(4)"],"by":{"1":"16"}},{"t":"usc","label":"15 U.S.C. § 1681f","url":"https://www.law.cornell.edu/uscode/text/15/1681f","by":{"1":"2, 16"}},{"t":"usc","label":"15 U.S.C. § 1681g","url":"https://www.law.cornell.edu/uscode/text/15/1681g","subs":["(a)(3)(C)","(g)(1)","(g)(1)(G)"],"by":{"1":"16, 15, 15"}},{"t":"usc","label":"15 U.S.C. § 1681i","url":"https://www.law.cornell.edu/uscode/text/15/1681i","subs":["(a)(1)","(a)(1)(A)","(a)(2)(A)"],"by":{"1":"2, 5, 5"}},{"t":"usc","label":"15 U.S.C. § 1681p","url":"https://www.law.cornell.edu/uscode/text/15/1681p","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 1681v","url":"https://www.law.cornell.edu/uscode/text/15/1681v","subs":["(a)"],"by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","subs":["(x)","(d)"],"by":{"1":"40","2":"9"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(a)","(k)","(o)"],"by":{"1":"40, 40, 40"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(b)(20)"],"by":{"1":"40"}},{"t":"law","label":"Pub. L. No. 93-579","url":"https://www.govinfo.gov/link/statute/88/1896","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/15/1602","subs":["(d)","(e)","(g)"],"by":{"1":"6, 18, 6, 18, 6, 18","2":"12, 12, 12"}},{"t":"usc","label":"15 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/15/1611","by":{"1":"23"}},{"t":"usc","label":"15 U.S.C. § 1612","url":"https://www.law.cornell.edu/uscode/text/15/1612","subs":["(b)"],"by":{"1":"6, 18, 23","2":"12"}},{"t":"usc","label":"15 U.S.C. § 1640","url":"https://www.law.cornell.edu/uscode/text/15/1640","subs":["(a)"],"by":{"1":"18","2":"12"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","subs":["(a)(6)"],"by":{"1":"15"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","by":{"1":"28"}},{"t":"usc","label":"15 U.S.C. § 2688","url":"https://www.law.cornell.edu/uscode/text/15/2688","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 229F","url":"https://www.law.cornell.edu/uscode/text/18/229F","subs":["(1)(A)"],"by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/28/1362","by":{"1":"29"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)","(c)"],"by":{"1":"39, 39"}},{"t":"usc","label":"42 U.S.C. § 6992e","url":"https://www.law.cornell.edu/uscode/text/42/6992e","subs":["(a)","(b)"],"by":{"1":"22","2":"15, 15"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(20)(D)"],"by":{"1":"47","2":"8"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Fitzgerald v. Barnstable School Committee","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Hammer v. Equifax Information Services., L.L.C.","cite":"974 F.3d 564","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/564/","by":{"2":"21"}},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"sum":"In Edelman v. Jordan, 415 U. S. 651, it was held that retroactive welfare benefits awarded by a Federal District Court to the plaintiff class, by reason of wrongful denial of benefits by Illinois officials prior to the entry of the court's order determining the wrongfulness of their actions, violated the Eleventh Amendment, and that in an action under 42 U. S. C. § 1983 \"a federal court's remedial power, consistent …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"op":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"usc","label":"15 U.S.C. § 1691","url":"https://www.law.cornell.edu/uscode/text/15/1691","by":{"2":"12"}},{"t":"law","label":"Pub. L. No. 104-93","url":"https://www.govinfo.gov/link/plaw/104/public/93","by":{"2":"19, 20"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"2":"12"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"21"}}]};